@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (Profile is null)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label fw-semibold">Display Name</label>
                    <input type="text" class="form-control" @bind="editName" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Email</label>
                    <input type="email" class="form-control" @bind="editEmail" />
                </div>

                <div class="mb-3">
                    <label class="form-label fw-semibold">Bio</label>
                    <textarea class="form-control" rows="4" @bind="editBio"></textarea>
                </div>
            </div>

            <div class="col-md-4">
                <div class="card text-center p-3">
                    <label class="form-label fw-semibold">Avatar Preview</label>
                    <div class="avatar-preview mx-auto mb-2">
                        @if (!string.IsNullOrWhiteSpace(Profile.AvatarUrl))
                        {
                            <img src="@Profile.AvatarUrl" alt="Avatar" class="rounded-circle" width="100" height="100" />
                        }
                        else
                        {
                            <div class="avatar-placeholder rounded-circle d-flex align-items-center justify-content-center">
                                <span class="fs-1">👤</span>
                            </div>
                        }
                    </div>
                    <small class="text-muted text-break">@Profile.AvatarUrl</small>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <div class="mt-3 d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @if (isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard" disabled="@isSaving">
                Discard Changes
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string editName = "";
    private string editEmail = "";
    private string editBio = "";
    private string? statusMessage;
    private bool isError;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !isSaving)
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        editName = Profile!.DisplayName;
        editEmail = Profile.Email;
        editBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = Profile! with { DisplayName = editName, Email = editEmail, Bio = editBio };
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully!";
            isError = false;
        }
        catch
        {
            statusMessage = "Failed to save profile. Please try again.";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }

    private void Discard()
    {
        ResetFields();
        statusMessage = null;
    }
}

.avatar-placeholder {
    width: 100px;
    height: 100px;
    background-color: var(--bs-secondary-bg, #e9ecef);
}

@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (Prefs is null)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">General</h6>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="emailNotif"
                           checked="@editEmailNotif" @onchange="e => editEmailNotif = (bool)e.Value!" />
                    <label class="form-check-label" for="emailNotif">
                        Email Notifications
                        <small class="d-block text-muted">Receive notifications via email</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="pushNotif"
                           checked="@editPushNotif" @onchange="e => editPushNotif = (bool)e.Value!" />
                    <label class="form-check-label" for="pushNotif">
                        Push Notifications
                        <small class="d-block text-muted">Receive browser push notifications</small>
                    </label>
                </div>

                <div class="form-check form-switch mb-3">
                    <input class="form-check-input" type="checkbox" id="weeklyDigest"
                           checked="@editWeeklyDigest" @onchange="e => editWeeklyDigest = (bool)e.Value!" />
                    <label class="form-check-label" for="weeklyDigest">
                        Weekly Digest
                        <small class="d-block text-muted">Receive a weekly summary email</small>
                    </label>
                </div>
            </div>
        </div>

        <div class="card mb-4">
            <div class="card-body">
                <h6 class="card-title mb-3">Muted Channels</h6>
                @if (AllChannels.Count == 0)
                {
                    <p class="text-muted">No channels available.</p>
                }
                else
                {
                    @foreach (var channel in AllChannels)
                    {
                        var isMuted = editMutedChannels.Contains(channel);
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@isMuted"
                                   @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"ch-{channel}")">
                                @channel
                                @if (isMuted)
                                {
                                    <span class="badge bg-secondary ms-1">Muted</span>
                                }
                            </label>
                        </div>
                    }
                }
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save Preferences
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    /// <summary>All channels available in the app (superset of muted).</summary>
    [Parameter]
    public List<string> AllChannels { get; set; } = [];

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool editEmailNotif;
    private bool editPushNotif;
    private bool editWeeklyDigest;
    private HashSet<string> editMutedChannels = [];
    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !isSaving)
        {
            editEmailNotif = Prefs.EmailNotifications;
            editPushNotif = Prefs.PushNotifications;
            editWeeklyDigest = Prefs.WeeklyDigest;
            editMutedChannels = [.. Prefs.MutedChannels];
        }
    }

    private void ToggleMute(string channel, bool muted)
    {
        if (muted)
            editMutedChannels.Add(channel);
        else
            editMutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new NotificationPrefs(editEmailNotif, editPushNotif, editWeeklyDigest, [.. editMutedChannels]);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Preferences saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="change-password-panel">
    <div class="card">
        <button class="card-header d-flex align-items-center justify-content-between w-100 bg-transparent border-0 text-start"
                @onclick="() => isExpanded = !isExpanded">
            <span class="fw-semibold">Change Password</span>
            <span>@(isExpanded ? "▲" : "▼")</span>
        </button>

        @if (isExpanded)
        {
            <div class="card-body">
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="currentPassword" />
                </div>

                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="newPassword" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Confirm New Password</label>
                    <input type="password" class="form-control" @bind="confirmPassword" />
                </div>

                @if (!string.IsNullOrEmpty(statusMessage))
                {
                    <div class="alert @(isError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
                        @statusMessage
                        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
                    </div>
                }

                <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                    @if (isUpdating)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Update Password
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? statusMessage;
    private bool isError;
    private bool isUpdating;

    private async Task UpdatePasswordAsync()
    {
        statusMessage = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            statusMessage = "Please fill in all password fields.";
            isError = true;
            return;
        }

        if (newPassword != confirmPassword)
        {
            statusMessage = "New password and confirmation do not match.";
            isError = true;
            return;
        }

        isUpdating = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            statusMessage = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch
        {
            statusMessage = "Failed to update password. Please check your current password.";
            isError = true;
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="active-sessions-table">
    <h6 class="mb-3">Active Sessions</h6>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th class="text-end">Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    @if (confirmingSessionId == session.Id)
                                    {
                                        <span class="me-2 text-danger small">Revoke this session?</span>
                                        <button class="btn btn-danger btn-sm me-1" @onclick="() => ConfirmRevokeAsync(session.Id)">
                                            Yes
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm" @onclick="CancelConfirm">
                                            No
                                        </button>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession>? Sessions { get; set; }

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        confirmingSessionId = sessionId;
    }

    private void CancelConfirm()
    {
        confirmingSessionId = null;
    }

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        await OnRevoke.InvokeAsync(sessionId);
        confirmingSessionId = null;
    }
}

@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    @if (Settings is null)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <ChangePasswordPanel OnChangePassword="HandlePasswordChange" />

        <div class="card my-4">
            <div class="card-body d-flex align-items-center justify-content-between">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        @if (Settings.TwoFactorEnabled)
                        {
                            <span class="text-success">● Enabled</span>
                        }
                        else
                        {
                            <span class="text-danger">● Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@Settings.TwoFactorEnabled" disabled
                           aria-label="Two-factor authentication status" />
                </div>
            </div>
            @if (Settings.LastPasswordChange.HasValue)
            {
                <div class="card-footer text-muted small">
                    Last password change: @Settings.LastPasswordChange.Value.ToString("f")
                </div>
            }
        </div>

        <ActiveSessionsTable Sessions="@Settings.Sessions"
                             CurrentSessionId="@CurrentSessionId"
