    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !isSaving)
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        editName = Profile!.DisplayName;
        editEmail = Profile.Email;
        editBio = Profile.Bio;
    }

