@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="active-sessions-table">
    <h6 class="mb-3">Active Sessions</h6>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover align-middle">
                <thead class="table-light">
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th class="text-end">Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        var isCurrent = session.Id == CurrentSessionId;
                        <tr>
                            <td>
                                @session.Device
                                @if (isCurrent)
                                {
                                    <span class="badge bg-success ms-1">Current</span>
                                }
                            </td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td class="text-end">
                                @if (!isCurrent)
                                {
                                    @if (confirmingSessionId == session.Id)
                                    {
                                        <span class="me-2 text-danger small">Revoke this session?</span>
                                        <button class="btn btn-danger btn-sm me-1" @onclick="() => ConfirmRevokeAsync(session.Id)">
                                            Yes
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm" @onclick="CancelConfirm">
                                            No
                                        </button>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession>? Sessions { get; set; }

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevoke { get; set; }

    private string? confirmingSessionId;

    private void RequestRevoke(string sessionId)
    {
        confirmingSessionId = sessionId;
    }

    private void CancelConfirm()
    {
        confirmingSessionId = null;
    }

    private async Task ConfirmRevokeAsync(string sessionId)
    {
        await OnRevoke.InvokeAsync(sessionId);
        confirmingSessionId = null;
    }
}

