toolArgs.file_text:
@using sv_67e6dd62b16048b5847dc40927889bf6.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (Settings is null)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(editTheme == theme)"
                                       @onchange="() => editTheme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(editFontSize == size)"
                                       @onchange="() => editFontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="editLanguage">
                            @foreach (var lang in Languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <div class="card mb-3">
                    <div class="card-body d-flex align-items-center justify-content-between">
                        <div>
                            <h6 class="mb-0">Compact Mode</h6>
                            <small class="text-muted">Reduce spacing for a denser layout</small>
                        </div>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@editCompactMode"
                                   @onchange="e => editCompactMode = (bool)e.Value!" />
                        </div>
                    </div>
                </div>
            </div>

            <div class="col-md-5">
                <AppearancePreview Theme="@editTheme"
                                   FontSize="@editFontSize"
                                   Language="@editLanguage"
                                   CompactMode="@editCompactMode" />
            </div>
        </div>

        @if (!string.IsNullOrEmpty(statusMessage))
        {
            <div class="alert alert-success alert-dismissible fade show mt-3" role="alert">
                @statusMessage
                <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string editTheme = "Light";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;
    private string? statusMessage;
    private bool isSaving;

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override void OnParametersSet()
    {
        if (Settings is not null && !isSaving)
        {
            editTheme = Settings.Theme;
            editFontSize = Settings.FontSize;
            editLanguage = Settings.Language;
            editCompactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var updated = new AppearanceSettings(editTheme, editFontSize, editLanguage, editCompactMode);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Appearance saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

.settings-dashboard {
    min-height: 70vh;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.5rem;
    overflow: hidden;
    background-color: var(--bs-body-bg, #fff);
}

.settings-content {
    overflow-y: auto;
}

